function firstWeekOfYear(n){let t=new Date(n,0,1),i=t.getDay(),u=i===0?-6:1-i,r=new Date(t);return r.setDate(t.getDate()+u),r}function formatDateNumber(n,t,i){let r=String(t).padStart(2,"0"),u=String(i).padStart(2,"0");return`${n}-${r}-${u}`}function formatDate(n){let t=n.getFullYear(),i=String(n.getMonth()+1).padStart(2,"0"),r=String(n.getDate()).padStart(2,"0");return`${t}-${i}-${r}`}function formDataAppendTime(n){let r=$("#timeUnit").val();n.append("TimeUnit",r);let t,i;switch(r){case"day":t=$("#startDate").val();i=$("#endDate").val();break;case"week":t=formatDate(firstWeekOfYear(parseInt($("#startWeekYear").val())).addDays(7*($("#startWeekWeek").val()-1)));i=formatDate(firstWeekOfYear(parseInt($("#endWeekYear").val())).addDays(7*($("#endWeekWeek").val()-1)));break;case"month":t=formatDateNumber($("#startMonthYear").val(),$("#startMonthMonth").val(),1);i=formatDateNumber($("#endMonthYear").val(),$("#endMonthMonth").val(),1);break;case"quarter":t=formatDateNumber($("#startQuarterYear").val(),$("#startQuarterQuarter").val()*3-2,1);i=formatDateNumber($("#endQuarterYear").val(),$("#endQuarterQuarter").val()*3-2,1);break;case"year":t=formatDateNumber($("#startYearInput").val(),1,1);i=formatDateNumber($("#endYearInput").val(),1,1)}return n.append("Start",t),n.append("End",i),n}Date.prototype.addDays=function(n){return this.setDate(this.getDate()+n),this};